/* ***********************   c16c3   **************************** */
function BBTcallsGENc16c3() {
	
	$(".title1").html("<b>Partition of Brussels<br>and its surroundings</b><br>based on phone calls<br>and a community detection algorithm<br>(3 communities)") ;
	
	$(".subtitle1").show().html("Cells covered by nearest tower with remarkably high interaction in terms of phone calls form a so-called <b>community</b> represented in a <b>single color</b><br><br>Black lines: limits of Provinces") ;
		
	$("#legendecontainer").hide();
	
	
	
	
	
	$("#shortcutB").off();
	$("#shortcutlabelB").html("Study area<br><i>Not available at a national scale</i>");
	
	
	$("#shortcutC").off();
	$("#shortcutlabelC").html("Resolution level<br><i>No other option available</i>");
	
	
	$("#shortcutD").off().show();
	$("#shortcutD").off().on("click", function(d) {
			$("#menuC1BBTDfull, #menuC1BBTDreduce").css("display", "block");
		});
	
	$("#shortcutsE, #shortcutsF").off().show();
	$("#shortcutslabelE, #shortcutslabelF").off().show();
	
		$("#shortcutE1").off().show().on("click", BBTcallsGENc14c4 ).on("click", LDG ).on("click", layersBBTphone );
		$("#shortcutE2").off().hide();
		$("#shortcutE3").off().hide();
	
		$("#shortcutF1").off().show().on("click", BBTdensPOPcallsGENc16c3 ).on("click", LDG ).on("click", layersBBTphoneplus );
		$("#shortcutF2").off().show().on("click", BBTdensBATcallsGENc16c3 ).on("click", LDG ).on("click", layersBBTphoneplus );
		$("#shortcutF3").off().hide();
		$("#shortcutF4").off().hide();
	
	
	
	
	
	$("#detailsaboutthismap")
	.html("<strong><b>Period and source</b></strong><br><ul><li>Source of data:<br>a major phone provider (for privacy reasons, cannot be shared)</li><li>Source of basemap: Voronoï cells around cellphone towers</li><li>Year: 2015</li></ul><strong><b>Data preparation and analysis </b>(community detection)</strong><br><br>Arnaud Adam") ;
	
	$("#commentsaboutthismap")
	.html("This partition of Brussels and its surroundings (Former Province of Brabant) is obtained by the <b>application of a community detection algorithm (The Louvain method) on phone calls</b> between towers located in the area. Each tower (aggregation of antennas located on the same structure) is represented by a cell constituted by the area closest to this tower. Each community can here be considered as an interaction basin in terms of communications. 3 communities are illustrated here, obtained with a resolution parameter equal to 1.6. Whatever the number of communities chosen, each of them is quite surprisingly contiguous: proximity matters even for non-physical communications.<br><br>Communities are displayed here as a <b>chorochromatic map</b>, each community being represented in a single color.<br><br>One community is centered on the eastern part of the Brussels Capital Region, excluding parts of the Region being on the western bank of the Brussels-Charleroi Canal, but including towers located in some other municipalities at the south (Drogenbos, Linkebeek or Sint-Genesius-Rode; municipalities with language facilities) or at the east (Tervuren). The limit between the two other communities broadly follows the linguistic border between Walloon Brabant and Flemish Brabant.") ;
	
	$("#downloadthismap")
	.html("To download a map, make a right-click on the format (.svg or .png), select 'save as', and specify the directory where you want to save it.<br><br><b>Communities only<br>(chorochromatic map)</b><br><a href=" + "http:/" + "/atlas.brussels/ATLAS/Download/BBTphoneGEN3.svg" + " target=" + "_new" + " proposed_file_name=" + "BBTphoneGEN3.svg" + "><button type=button" + ">.svg</button></a> & <a href=" + "http:/" + "/atlas.brussels/ATLAS/Download/BBTphoneGEN3.png" + " target=" + "_new" + " proposed_file_name=" + "BBTphoneGEN3.png" + "><button type=button" + ">.png</button></a><br><br><b>Communities on a layer of population density</b><br><a href=" + "http:/" + "/atlas.brussels/ATLAS/Download/BBTphoneGEN3denspop.svg" + " target=" + "_new" + " proposed_file_name=" + "BBTphoneGEN3denspop.svg" + "><button type=button" + ">.svg</button></a> & <a href=" + "http:/" + "/atlas.brussels/ATLAS/Download/BBTphoneGEN3denspop.png" + " target=" + "_new" + " proposed_file_name=" + "BBTphoneGEN3denspop.png" + "><button type=button" + ">.png</button></a><br><br><b>Communities on a layer of built-up density</b><br><a href=" + "http:/" + "/atlas.brussels/ATLAS/Download/BBTphoneGEN3densbat.svg" + " target=" + "_new" + " proposed_file_name=" + "BBTphoneGEN3densbat.svg" + "><button type=button" + ">.svg</button></a> & <a href=" + "http:/" + "/atlas.brussels/ATLAS/Download/BBTphoneGEN3densbat.png" + " target=" + "_new" + " proposed_file_name=" + "BBTphoneGEN3densbat.png" + "><button type=button" + ">.png</button></a>") ;
	
	chemindata = "ATLAS/GEOdata/BBTcallsGENc16c3.json";
	

	color = d3.scaleOrdinal()
        		.domain([1,2,3])
		.range(["#9bb1e8","#d8a591","#ddd6a5", "#ffffff"]);
	
	
	load(chemindata, legendtext, color) ;	
	} // layers OK
