/* ***********************   c12c4   **************************** */
function BBTcallsDAYc12c4() {
	
	$(".title1").html("<b>Partition of Brussels<br>and its surroundings</b><br>based on daytime phone calls<br>and a community detection algorithm<br>(4 communities)") ;
	
	$(".subtitle1").show().html("Cells covered by nearest tower with remarkably high interaction in terms of daytime phone calls form a so-called <b>community</b> represented in a <b>single color</b><br><br><i>White spatial units show only internal calls</i>") ;
	
	$("#legendecontainer").hide();
	
	
	
	$("#shortcutB").off();
	$("#shortcutlabelB").html("Study area<br><i>Not available at a national scale</i>");
	
	
	$("#shortcutC").off();
	$("#shortcutlabelC").html("Resolution level<br><i>No other option available</i>");
	
	
	$("#shortcutD").off().show();
	$("#shortcutD").off().on("click", function(d) {
			$("#menuC1BBTEfull, #menuC1BBTEreduce").css("display", "block");
		});
	
	$("#shortcutsE, #shortcutsF").off().show();
	$("#shortcutslabelE, #shortcutslabelF").off().show();
	
		$("#shortcutE1").off().show().on("click", BBTcallsDAYc10c6 ).on("click", LDG ).on("click", layersBBTphone );
		$("#shortcutE2").off().show().on("click", BBTcallsDAYc20c3 ).on("click", LDG ).on("click", layersBBTphone );
		$("#shortcutE3").off().show().on("click", BBTcallsDAYc14c4 ).on("click", LDG ).on("click", layersBBTphone );
	
		$("#shortcutF1").off().show().on("click", BBTdensPOPcallsDAYc12c4 ).on("click", LDG ).on("click", layersBBTphoneplus );
		$("#shortcutF2").off().show().on("click", BBTdensBATcallsDAYc12c4 ).on("click", LDG ).on("click", layersBBTphoneplus );
		$("#shortcutF3").off().hide();
		$("#shortcutF4").off().hide();
	
	
	
	$("#detailsaboutthismap")
	.html("<strong><b>Period and source</b></strong><br><ul><li>Source of data:<br>a major phone provider (for privacy reasons, cannot be shared)</li><li>Source of basemap: Voronoï cells around cellphone towers</li><li>Year: 2015</li></ul><strong><b>Data preparation and analysis </b>(community detection)</strong><br><br>Arnaud Adam") ;
	
	$("#commentsaboutthismap")
	.html("This partition of Brussels and its surroundings (Former Province of Brabant) is obtained by the <b>application of a community detection algorithm (The Louvain method) on daytime-only phone calls</b> between towers located in the area. Each tower (aggregation of antennas located on the same structure) is represented by a cell constituted by the area closest to this tower. Each community can here be considered as an interaction basin in terms of communications. 4 communities are illustrated here, obtained with a resolution parameter equal to 1.2 (another partition in 4 communities is obtained with a resolution parameter of 1.4). Whatever the number of communities chosen, each of them is quite surprisingly contiguous: proximity matters even for non-physical communications.<br><br>Communities are displayed here as a <b>chorochromatic map</b>, each community being represented in a single color.<br><br>One community is centered on the eastern part of the Brussels Capital Region, excluding parts of the Region being on the western bank of the Brussels-Charleroi Canal, but including towers located in some other municipalities at the south (Drogenbos, Linkebeek or Sint-Genesius-Rode; municipalities with language facilities) or at the east (Tervuren). Other towers of the Flemish Brabant are split in two communities along an axis going from Grimbergen to Asse, and most of the Walloon towers are grouped in a single community.") ;
	
	$("#downloadthismap")
	.html("To download a map, make a right-click on the format (.svg or .png), select 'save as', and specify the directory where you want to save it.<br><br><b>Communities only<br>(chorochromatic map)</b><br><a href=" + "http:/" + "/atlas.brussels/ATLAS/Download/BBTphoneDAY4bis.svg" + " target=" + "_new" + " proposed_file_name=" + "BBTphoneDAY4bis.svg" + "><button type=button" + ">.svg</button></a> & <a href=" + "http:/" + "/atlas.brussels/ATLAS/Download/BBTphoneDAY4bis.png" + " target=" + "_new" + " proposed_file_name=" + "BBTphoneDAY4bis.png" + "><button type=button" + ">.png</button></a><br><br><b>Communities on a layer of population density</b><br><a href=" + "http:/" + "/atlas.brussels/ATLAS/Download/BBTphoneDAY4bisdenspop.svg" + " target=" + "_new" + " proposed_file_name=" + "BBTphoneDAY4bisdenspop.svg" + "><button type=button" + ">.svg</button></a> & <a href=" + "http:/" + "/atlas.brussels/ATLAS/Download/BBTphoneDAY4bisdenspop.png" + " target=" + "_new" + " proposed_file_name=" + "BBTphoneDAY4bisdenspop.png" + "><button type=button" + ">.png</button></a><br><br><b>Communities on a layer of built-up density</b><br><a href=" + "http:/" + "/atlas.brussels/ATLAS/Download/BBTphoneDAY4bisdensbat.svg" + " target=" + "_new" + " proposed_file_name=" + "BBTphoneDAY4bisdensbat.svg" + "><button type=button" + ">.svg</button></a> & <a href=" + "http:/" + "/atlas.brussels/ATLAS/Download/BBTphoneDAY4bisdensbat.png" + " target=" + "_new" + " proposed_file_name=" + "BBTphoneDAY4bisdensbat.png" + "><button type=button" + ">.png</button></a>") ;
	
	chemindata = "ATLAS/GEOdata/BBTcallsDAYc12c4.json";
	

	color = d3.scaleOrdinal()
        		.domain([1,2,3,6])
		.range([
		"#9bb1e8", // bleu sud
		"#d4b0d9", // violet centre
		"#d8a591", // orange nord
		"#ddd6a5", // jaune ouest
		
		"#ffffff"]);

	
	
	load(chemindata, legendtext, color) ;	
	} // layers OK
